      "content": "import { describe, expect, test } from 'bun:test';
import { covers, FakeLlm } from '@agentic-ddd/testing';
import { OperatorRuntime } from '@agentic-ddd/runtime';
import { TaskOperator } from '../operators/task.operator';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskCreated, TaskCompleted } from '../domain/task.events';

describe('task-operator', () => {
  test(covers(['criterion:0001/tools', 'operator:task-operator'], 'usa somente create_task e complete_task e publica os dois eventos no fluxo create->complete'), async () => {
    const llm = new FakeLlm([
      { stopReason: 'tool_calls', content: [{ type: 'tool_call', id: 'call-1', name: 'create_task', input: { task_id: 't1', title: '  titulo  ' } }] },
      { stopReason: 'tool_calls', content: [{ type: 'tool_call', id: 'call-2', name: 'complete_task', input: { task_id: 't1' } }] },
      { stopReason: 'end', content: [{ type: 'text', text: 'Tarefa t1 criada e concluida.' }] },
    ]);
    const tasks = new InMemoryTaskRepository();
    const runtime = new OperatorRuntime({ llm, modules: [{ name: 'tasks', path: 'app' }] });
    const useCases = new Map();
    useCases.set(CreateTask, new CreateTask(tasks));
    useCases.set(CompleteTask, new CompleteTask(tasks));
    await runtime.register(TaskOperator, useCases);

    const result = await runtime.run('task-operator', { message: 'Crie a tarefa t1 e depois conclua a tarefa t1.' });

    expect(result.status).toBe('completed');
    expect(result.output).toBe('Tarefa t1 criada e concluida.');

    expect(llm.requests).toHaveLength(3);
    expect(llm.requests[0]?.tools.map((tool) => tool.name)).toEqual(['complete_task', 'create_task']);

    const usedTools = result.steps.flatMap((step) => step.tools.map((tool) => tool.call.name));
    expect(usedTools).toEqual(['create_task', 'complete_task']);
    expect(new Set(usedTools)).toEqual(new Set(['create_task', 'complete_task']));

    expect(result.events).toHaveLength(2);
    expect(result.events[0]).toBeInstanceOf(TaskCreated);
    expect(result.events[1]).toBeInstanceOf(TaskCompleted);
    expect(result.events.map((event) => ({ name: event.name, payload: event.payload }))).toEqual([
      { name: 'TaskCreated', payload: { taskId: 't1', title: 'titulo' } },
      { name: 'TaskCompleted', payload: { taskId: 't1' } },
    ]);
    expect((await tasks.findById('t1'))?.status).toBe('completed');
  });
});
